// or unknown names return nil so verifyAgentsLaunchable can refuse them.
func TestLaunchableSpawnerFor_KnownAgents(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name        string
		agent       string
		wantNil     bool
		description string
	}{
